START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023102059_AddSponsors') THEN
    ALTER TABLE "StreamOverlays" ADD "SponsorMode" integer NOT NULL DEFAULT 0;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023102059_AddSponsors') THEN
    CREATE TABLE "Sponsors" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "Name" character varying(80) NOT NULL,
        "LinkUrl" character varying(300),
        "LogoBytes" bytea,
        "LogoContentType" character varying(30),
        "LogoVersion" integer NOT NULL,
        "Tier" integer NOT NULL,
        "SortOrder" integer NOT NULL,
        "ShowOn" integer NOT NULL,
        "IsEnabled" boolean NOT NULL,
        "StartsAt" timestamp with time zone,
        "EndsAt" timestamp with time zone,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Sponsors" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Sponsors_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023102059_AddSponsors') THEN
    CREATE TABLE "SponsorExposures" (
        "SponsorId" integer NOT NULL,
        "Day" timestamp with time zone NOT NULL,
        "Placement" integer NOT NULL,
        "Views" bigint NOT NULL,
        "Seconds" bigint NOT NULL,
        CONSTRAINT "PK_SponsorExposures" PRIMARY KEY ("SponsorId", "Day", "Placement"),
        CONSTRAINT "FK_SponsorExposures_Sponsors_SponsorId" FOREIGN KEY ("SponsorId") REFERENCES "Sponsors" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023102059_AddSponsors') THEN
    CREATE INDEX "IX_Sponsors_CompetitionId" ON "Sponsors" ("CompetitionId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261023102059_AddSponsors') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261023102059_AddSponsors', '10.0.8');
    END IF;
END $EF$;
COMMIT;

